<?php $this->layout('_studio'); $categoryMap=[]; foreach($categories as $category){$categoryMap[$category->id]=$category;} ?>
<section class="studio-page-head organic-page-header"><div><p class="organic-eyebrow">Conhecimento</p><h1 class="organic-page-title">Suporte</h1><p class="organic-page-description">Crie tutoriais e matérias que também serão usados como ajuda contextual no MovesOS.</p></div><div class="actions organic-page-actions"><button class="organic-btn" type="button" data-support-folder-open><ion-icon name="folder-open-outline"></ion-icon> Nova pasta</button><a class="organic-btn organic-btn-primary" href="<?= url('/studio/support/article') ?>"><ion-icon name="add-circle-outline"></ion-icon> Nova matéria</a></div></section>
<section class="studio-support-summary organic-grid organic-grid-3"><?php foreach($categories as $category): ?><a class="organic-card organic-card-hover" href="<?= url('/studio/support/category/'.$category->id) ?>"><i><ion-icon name="<?= htmlspecialchars($category->icon) ?>"></ion-icon></i><span><strong><?= htmlspecialchars($category->title) ?></strong><small><?= $category->articles()->count() ?> matéria(s)</small></span><ion-icon name="chevron-forward-outline"></ion-icon></a><?php endforeach; ?></section>
<section class="studio-panel studio-support-list organic-card"><header class="organic-card-header"><div><p class="organic-eyebrow">Matérias</p><h2 class="organic-card-title">Conteúdo cadastrado</h2></div><span class="organic-badge organic-badge-neutral"><?= count($articles) ?> matérias</span></header><div class="studio-table-wrap organic-table-wrapper"><table class="studio-table organic-table"><thead><tr><th>Título</th><th>Categoria</th><th>Status</th><th>Visualizações</th><th>Avaliação</th><th></th></tr></thead><tbody><?php if(!$articles): ?><tr><td class="organic-table-empty" colspan="6">Nenhuma matéria cadastrada.</td></tr><?php endif; ?><?php foreach($articles as $article): ?><tr><td><strong><?= htmlspecialchars($article->title) ?></strong><small><?= htmlspecialchars($article->summary) ?></small></td><td><?= htmlspecialchars($categoryMap[$article->category_id]->title ?? 'Sem categoria') ?></td><td><span class="organic-badge <?= $article->status==='published'?'organic-badge-success':'organic-badge-neutral' ?>"><?= $article->status==='published'?'Publicada':'Rascunho' ?></span></td><td><?= (int)$article->views ?></td><td><span class="studio-helpful"><ion-icon name="thumbs-up-outline"></ion-icon><?= (int)$article->helpful_yes ?> <ion-icon name="thumbs-down-outline"></ion-icon><?= (int)$article->helpful_no ?></span></td><td><a href="<?= url('/studio/support/article/'.$article->id) ?>">Editar</a></td></tr><?php endforeach; ?></tbody></table></div></section>
<div class="studio-simple-modal" data-support-folder-modal aria-hidden="true" role="dialog" aria-modal="true" aria-labelledby="support-folder-title"><div><header><div><small>ORGANIZAÇÃO</small><h2 id="support-folder-title">Nova pasta de suporte</h2><p>Crie uma categoria para agrupar matérias relacionadas.</p></div><button type="button" data-support-folder-close aria-label="Fechar"><ion-icon name="close-outline"></ion-icon></button></header><form class="studio-form" action="<?= url('/studio/support/category') ?>" method="post"><?= csrf_input() ?><input type="hidden" name="action" value="save"><label>Nome da pasta<input name="title" minlength="3" required></label><label>Descrição<textarea name="description" rows="3"></textarea></label><div class="studio-fields-two"><label>Ícone<input name="icon" value="folder-outline" pattern="[a-z0-9-]+"></label><label>Posição<input type="number" name="position" min="1" value="<?= count($categories)+1 ?>"></label></div><input type="hidden" name="status" value="active"><footer><button class="studio-btn" type="button" data-support-folder-close>Cancelar</button><button class="studio-btn primary" type="submit"><ion-icon name="folder-outline"></ion-icon>Criar pasta</button></footer></form></div></div>
<?php $this->start('scripts'); ?><script>const supportFolderModal=document.querySelector('[data-support-folder-modal]');const setSupportFolderModal=open=>{supportFolderModal?.classList.toggle('open',open);supportFolderModal?.setAttribute('aria-hidden',String(!open));if(open)setTimeout(()=>supportFolderModal.querySelector('input[name="title"]')?.focus(),80)};document.querySelector('[data-support-folder-open]')?.addEventListener('click',()=>setSupportFolderModal(true));document.querySelectorAll('[data-support-folder-close]').forEach(button=>button.addEventListener('click',()=>setSupportFolderModal(false)));supportFolderModal?.addEventListener('click',event=>{if(event.target===supportFolderModal)setSupportFolderModal(false)});document.addEventListener('keydown',event=>{if(event.key==='Escape')setSupportFolderModal(false)});</script><?php $this->end(); ?>
